@Component("paymentContract-handler")
@ProcessingGroup("paymentContract-processing-group")
public class PaymentContractEventHandler {
	
	// core constructor
	PaymentContractEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePaymentContractEvent
     */
    @EventHandler
    public void handle( CreatePaymentContractEvent event) {
        entityManager.persist(new PaymentContract(event.getPaymentContractId(), event.getContractNumber(), event.getPricingPlanCode(), event.getMerchant(), event.getAcquirer(), event.getStatus()));
    }

    /*
     * @param	event UpdatePaymentContractEvent
     */
    @EventHandler
    public PaymentContract handle( UpdatePaymentContractEvent event) {
    	entityManager.merge(new PaymentContract(event.getPaymentContractId(), event.getContractNumber(), event.getPricingPlanCode(), event.getMerchant(), event.getAcquirer(), event.getStatus()));
    }
    
    /*
     * @param	event DeletePaymentContractEvent
     */
    @EventHandler
    public void on( DeletePaymentContractEvent event) {
    	PaymentContract entity = new PaymentContract();
   
    	// ------------------------------------------
    	// apply the PaymentContractId
    	// ------------------------------------------
    	entity.setPaymentContractId( event.getPaymentContractId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PaymentContractRepository paymentContractEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PaymentContractEventHandler.class.getName());

}
